<header class="page-header"><div><p class="eyebrow"><?= $company['archived_at']===null?'Active company':'Archived company' ?></p><h1><?= $escape($company['name']) ?></h1><p><?= $escape($company['industry']??'') ?><?= $company['industry']&&$company['location']?' · ':'' ?><?= $escape($company['location']??'') ?></p></div><div class="form-actions"><a class="button" href="<?= $escape($editUrl) ?>">Edit company</a><?php if($company['archived_at']===null):?><a href="<?= $escape($newContactUrl) ?>">Add contact</a><?php endif;?></div></header>
<dl class="record-details"><div><dt>Website</dt><dd><?php if($company['website']):?><a href="<?= $escape($company['website']) ?>" rel="noopener noreferrer"><?= $escape($company['website']) ?></a><?php else:?>—<?php endif;?></dd></div><div><dt>Employees</dt><dd><?= $escape($company['employee_range']??'—') ?></dd></div><div><dt>Revenue</dt><dd><?= $escape($company['revenue_range']??'—') ?></dd></div><div><dt>Notes</dt><dd class="preserve-lines"><?= $escape($company['notes']??'—') ?></dd></div></dl>
<section><div class="page-header"><div><h2>Contacts</h2><p>Active and archived people attached to this company.</p></div></div>
<?php if($contacts===[]):?><div class="empty-state"><h3>No contacts</h3><p>This company can remain useful without a known person.</p></div><?php else:?><div class="table-scroll"><table><thead><tr><th>Contact</th><th>Role</th><th>Email</th><th>State</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody>
<?php foreach($contacts as $contact):?><tr><th><a href="<?= $escape($contactEditUrl((int)$contact['id'])) ?>"><?= $escape(trim(($contact['first_name']??'').' '.($contact['last_name']??''))) ?></a></th><td><?= $escape($contact['role']??'—') ?></td><td><?= $escape($contact['email']??'—') ?></td><td><?= $contact['archived_at']===null?'Active':'Archived' ?></td><td><form method="post" action="<?= $escape($contact['archived_at']===null?$contactArchiveUrl((int)$contact['id']):$contactRestoreUrl((int)$contact['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($contact['version']) ?>"><?php if($contact['archived_at']!==null):?><label class="checkbox-field"><input type="checkbox" name="confirm_duplicate" value="1"> Confirm duplicates</label><?php endif;?><button type="submit"><?= $contact['archived_at']===null?'Archive':'Restore' ?></button></form></td></tr><?php endforeach;?>
</tbody></table></div><?php endif;?></section>
<section class="settings-panel"><h2><?= $company['archived_at']===null?'Archive company':'Restore company' ?></h2><form method="post" action="<?= $escape($company['archived_at']===null?$archiveUrl:$restoreUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($company['version']) ?>"><?php if($company['archived_at']===null):?><label class="checkbox-field"><input type="checkbox" name="confirm_contacts" value="1"> Keep active contacts attached without archiving them.</label><?php else:?><label class="checkbox-field"><input type="checkbox" name="confirm_duplicate" value="1"> Restore even if a potential duplicate exists.</label><?php endif;?><button class="button button--danger" type="submit"><?= $company['archived_at']===null?'Archive company':'Restore company' ?></button></form></section><p><a href="<?= $escape($indexUrl) ?>">Back to companies</a></p>
